using System.Net.Mail;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.DataProtection;
using Sales360.Domain;
using Npgsql;

namespace Sales360.Api;

public static class Accounts
{
    public static readonly string[] AccessRoles=["Administrator","Super user","User"];
    public static readonly string[] WorkflowRoles=["None","Accountant","Reviewer 1","Reviewer 2","Approver","Finance Administrator","Collections Officer","Auditor"];
    public static string Company(HttpContext h)=>h.User.FindFirstValue("company")??throw new UnauthorizedAccessException();
    public static string Actor(HttpContext h)=>h.User.FindFirstValue(ClaimTypes.NameIdentifier)??throw new UnauthorizedAccessException();
    public static void Administrator(HttpContext h){if(!h.User.IsInRole("Administrator"))throw new UnauthorizedAccessException("Only an Administrator can manage users and assign roles.");}
    public static string Email(string input)
    {
        var email=input.Trim().ToLowerInvariant();Billing.Require(email.Length is >3 and <=254&&!email.Contains('\r')&&!email.Contains('\n')&&MailAddress.TryCreate(email,out var parsed)&&parsed.Address==email&&email.Contains('@'),"Enter a valid email address.");return email;
    }
    public static void Password(string password)=>Billing.Require(password.Length is >=12 and <=128,"Use a password between 12 and 128 characters.");
    public static string Secret(JsonNode input,string field="password")=>input[field]?.GetValue<string>()??"";
    static async Task<string> TokenCompany(Store store,string hash,string purpose){await using var c=await store.Open();return (await Store.One(c,"SELECT u.company_id FROM identity_token t JOIN app_user u ON u.id=t.user_id WHERE token_hash=@p0 AND purpose=@p1 AND consumed_at IS NULL AND expires_at>now()",hash,purpose)).Text("company_id");}
    public static async Task ValidateSession(CookieValidatePrincipalContext context)
    {
        var store=context.HttpContext.RequestServices.GetRequiredService<Store>();await using var c=await store.Open();
        var rows=await Store.Rows(c,"SELECT company_id,session_version FROM app_user WHERE id=@p0 AND active AND account_status='Approved'",context.Principal?.FindFirstValue(ClaimTypes.NameIdentifier)??"");
        if(rows.Count!=1||rows[0]!.Text("company_id")!=context.Principal?.FindFirstValue("company")||rows[0]!.Text("session_version")!=(context.Principal?.FindFirstValue("session_version")??"0")){context.RejectPrincipal();await context.HttpContext.SignOutAsync();}
    }
    public static async Task SignIn(HttpContext h,JsonObject user)
    {
        var claims=new List<Claim>{new(ClaimTypes.NameIdentifier,user.Text("id")),new(ClaimTypes.Name,user.Text("name")),new(ClaimTypes.Role,user.Text("access_role")),new("company",user.Text("company_id")),new("session_version",user.Text("session_version")),new("workflow_role",user.Text("role")),new("email",user.Text("email")),new("work_areas",user["work_areas"]?.ToJsonString()??"[]")};
        if(user.Text("role")!="None")claims.Add(new(ClaimTypes.Role,user.Text("role")));
        if(user.Text("access_role")=="Administrator"&&!claims.Any(x=>x.Value=="System Administrator"))claims.Add(new(ClaimTypes.Role,"System Administrator"));
        await h.SignInAsync(new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme)));
    }
    public static async Task QueueMail(NpgsqlConnection c,IdentityMail mail,JsonNode user,string subject,string body)
    {
        var id=Guid.NewGuid().ToString("N");var encrypted=mail.Protect(JsonSerializer.Serialize(new IdentityMessage(user.Text("email")!=""?user.Text("email"):user.Text("username")+"@offline.invalid",subject,body)));
        await Store.Exec(c,"INSERT INTO identity_mail(id,company_id,user_id,encrypted_payload) VALUES(@p0,@p1,@p2,@p3)",id,user.Text("company_id"),user.Text("id"),encrypted);
    }
    public static async Task Token(NpgsqlConnection c,IdentityMail mail,JsonNode user,string purpose)
    {
        // Repeated requests are throttled per account as well as by the public IP limiter.
        var count=(await Store.One(c,"SELECT count(*) AS count FROM identity_token WHERE user_id=@p0 AND purpose=@p1 AND created_at>now()-interval '1 hour'",user.Text("id"),purpose)).Integer("count");
        if(count>=5)return;
        var recent=await Store.Rows(c,"SELECT id FROM identity_token WHERE user_id=@p0 AND purpose=@p1 AND created_at>now()-interval '60 seconds'",user.Text("id"),purpose);if(recent.Count>0)return;
        var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();
        await Store.Exec(c,"UPDATE identity_token SET consumed_at=now() WHERE user_id=@p0 AND purpose=@p1 AND consumed_at IS NULL",user.Text("id"),purpose);
        await Store.Exec(c,"INSERT INTO identity_token(id,user_id,purpose,token_hash,expires_at) VALUES(@p0,@p1,@p2,@p3,now()+(@p4 * interval '1 minute'))",Guid.NewGuid().ToString("N"),user.Text("id"),purpose,Store.Hash(token),purpose=="reset"?30:1440);
        // Fragment keeps the bearer token out of web-server URLs and referrers.
        var url=mail.BaseUrl+"/#"+(purpose=="reset"?"reset-password":"verify-email")+"="+token;
        await QueueMail(c,mail,user,purpose=="reset"?"Reset your SALES360 password":"Verify your SALES360 email",purpose=="reset"?$"A password reset was requested for your SALES360 account.\n\nOpen this link within 30 minutes:\n{url}\n\nThis link works once. If you did not request this, ignore this email.":$"Welcome to SALES360.\n\nVerify your email using this link within 24 hours:\n{url}\n\nAn Administrator must also approve your account and assign your role before you can sign in.");
    }
    public static void Map(WebApplication app,RouteGroupBuilder api,Store store,IdentityMail mail)
    {
        api.MapPost("/auth/change-password",async(HttpContext h,JsonObject b)=>{
            Password(Secret(b));Billing.Require(Secret(b)==Secret(b,"confirm_password"),"Passwords do not match.");Billing.Require(Secret(b)!=Secret(b,"current_password"),"Choose a different new password.");
            await store.Transaction(Company(h),async c=>{var user=await Store.One(c,"SELECT * FROM app_user WHERE company_id=@p0 AND id=@p1 FOR UPDATE",Company(h),Actor(h));Billing.Require(Secret(b,"current_password").Length<=128&&Store.Verify(Secret(b,"current_password"),user.Text("password_hash")),"Current password is incorrect.");await Store.Exec(c,"UPDATE app_user SET password_hash=@p0,session_version=session_version+1 WHERE id=@p1",Store.Password(Secret(b)),Actor(h));await Store.Exec(c,"UPDATE identity_token SET consumed_at=now() WHERE user_id=@p0 AND consumed_at IS NULL",Actor(h));await Store.Exec(c,"UPDATE identity_mail SET state='Cancelled',encrypted_payload='',updated_at=now() WHERE user_id=@p0 AND state='Pending'",Actor(h));await Store.Audit(c,Company(h),Actor(h),"Password changed",Actor(h),new{sessionsRevoked=true});return 0;});await h.SignOutAsync();return new{message="Password changed. All sessions have been signed out. Sign in with your new password."};
        }).RequireRateLimiting("identity");
        api.MapPost("/users/{id}/recovery",async(HttpContext h,string id)=>{
            Administrator(h);await store.Transaction(Company(h),async c=>{var user=await Store.One(c,"SELECT * FROM app_user WHERE company_id=@p0 AND id=@p1 AND active AND account_status='Approved' FOR UPDATE",Company(h),id);await Token(c,mail,user,"reset");await Store.Audit(c,Company(h),Actor(h),"Administrator requested account recovery",id,new{purpose="One-use password reset link"});return 0;});return new{message="Recovery requested. Refresh the recovery mailbox after a moment. Repeated requests are limited to one per minute."};
        }).RequireRateLimiting("identity");
        api.MapGet("/auth-mail/recovery",async(HttpContext h)=>{
            Administrator(h);h.Response.Headers.CacheControl="no-store";Billing.Require(mail.IsOffline,"Local recovery mailbox is available only in offline mode.");await using var c=await store.Open();var jobs=await Store.Rows(c,"SELECT m.id,m.provider_reference,u.email,u.username,u.name FROM identity_mail m JOIN app_user u ON u.id=m.user_id WHERE m.company_id=@p0 AND m.state='Local mailbox' AND EXISTS(SELECT 1 FROM identity_token t WHERE t.user_id=m.user_id AND t.purpose='reset' AND t.consumed_at IS NULL AND t.expires_at>now()) ORDER BY m.created_at DESC LIMIT 50",Company(h));var messages=new JsonArray();
            foreach(var job in jobs){var file=job!.Text("provider_reference");if(file!=job.Text("id")+".eml")continue;var path=Path.Combine(mail.MailboxDirectory,file);if(!File.Exists(path))continue;var content=await File.ReadAllTextAsync(path);var match=System.Text.RegularExpressions.Regex.Match(content,@"#reset-password=([a-f0-9]{64})");if(!match.Success)continue;var hash=Store.Hash(match.Groups[1].Value);if((await Store.Rows(c,"SELECT id FROM identity_token WHERE token_hash=@p0 AND purpose='reset' AND consumed_at IS NULL AND expires_at>now()",hash)).Count==0)continue;var url=mail.BaseUrl+"/#reset-password="+match.Groups[1].Value;messages.Add(new JsonObject{["name"]=job.Text("name"),["email"]=job.Text("email"),["username"]=job.Text("username"),["url"]=url,["subject"]="Reset your SALES360 password",["body"]="Open this link on the SALES360 computer within 30 minutes and choose a new password:\n"+url+"\n\nThe link works once. The application must be running. Do not forward it."});}
            await Store.Audit(c,Company(h),Actor(h),"Recovery mailbox viewed","identity-mail",new{count=messages.Count});return messages;
        });
        object Notice(string kind)=>new{message=mail.IsOffline?(kind=="reset"?"If an eligible account exists, a recovery link is saved to the protected offline mailbox. Ask your Administrator for local recovery.":"Your local account request is recorded. Ask your Administrator to approve access. Offline mode does not verify ownership of an email inbox."):kind=="reset"?"If an eligible account exists, a password reset link will be sent to its registered email address.":"If registration is eligible, a verification link will be sent. After verification, an Administrator must approve access.",delivery=mail.PublicStatus};
        app.MapGet("/api/auth/config",async()=>{await using var c=await store.Open();return new{signupEnabled=!mail.IsOffline&&mail.SignupCompany!=""&&mail.Enabled,emailDelivery=mail.PublicStatus,offline=mail.IsOffline,roles=AccessRoles,workAreas=AreaAccess.Areas,setupRequired=(await Store.One(c,"SELECT count(*) AS count FROM first_admin_setup WHERE consumed_at IS NULL")).Integer("count")>0};});
        app.MapPost("/api/auth/signup",async(JsonObject b)=>{
            Billing.Require(!mail.IsOffline,"Ask your System Administrator to create your account in Setting > USER management.");Billing.Require(mail.Enabled&&mail.SignupCompany!="","Registration requires email delivery and a configured signup organization.");var identifier=Enrollment.Identifier(b.Text("identifier")!=""?b.Text("identifier"):b.Text("email"),mail.IsOffline);var email=identifier.Email;var username=identifier.Username;var password=Secret(b);Password(password);Billing.Require(password==Secret(b,"confirm_password"),"Passwords do not match.");var name=b.Text("name");Billing.Require(name.Length is >=2 and <=120,"Enter your full name (2–120 characters).");var passwordHash=Store.Password(password);
            await store.Transaction(mail.SignupCompany,async c=>{await Store.One(c,"SELECT id FROM company WHERE id=@p0",mail.SignupCompany);await Store.Exec(c,"SELECT pg_advisory_xact_lock(hashtext(@p0))","identity:"+(email??username));Billing.Require((await Store.One(c,"SELECT count(*) AS count FROM first_admin_setup WHERE consumed_at IS NULL")).Integer("count")==0,"Enroll the first Administrator before requesting user accounts.");var existing=await Store.Rows(c,"SELECT * FROM app_user WHERE lower(email)=@p0 OR lower(username)=@p1 OR (email IS NULL AND lower(id)=@p1)",email,username);if(existing.Count==0){var id=Guid.NewGuid().ToString("N");await Store.Exec(c,"INSERT INTO app_user(id,company_id,name,role,password_hash,active,email,username,access_role,account_status,work_areas) VALUES(@p0,@p1,@p2,'None',@p3,false,@p4,@p5,'User','Pending','[]')",id,mail.SignupCompany,name,passwordHash,email,username);var user=await Store.One(c,"SELECT * FROM app_user WHERE id=@p0",id);if(email!=null)await Token(c,mail,user,"verify");await Store.Audit(c,mail.SignupCompany,"registration","Email signup requested",id,new{accountStatus="Pending",accessRole="User"});}return 0;});return Results.Ok(Notice("verify"));
        }).RequireRateLimiting("identity");
        app.MapPost("/api/auth/forgot-password",async(JsonObject b)=>{
            Billing.Require(mail.Enabled,"Email delivery is not configured. Contact your Administrator.");var email=b.Text("email").ToLowerInvariant();Enrollment.Identifier(email,mail.IsOffline);var started=DateTimeOffset.UtcNow;
            await store.Transaction("identity:"+email,async c=>{var users=await Store.Rows(c,"SELECT * FROM app_user WHERE (lower(email)=@p0 OR lower(username)=@p0) AND (email_verified OR @p1) AND active AND account_status='Approved'",email,mail.IsOffline);if(users.Count==1)await Token(c,mail,users[0]!,"reset");return 0;});var delay=TimeSpan.FromMilliseconds(300)-(DateTimeOffset.UtcNow-started);if(delay>TimeSpan.Zero)await Task.Delay(delay);return Results.Ok(Notice("reset"));
        }).RequireRateLimiting("identity");
        app.MapPost("/api/auth/resend-verification",async(JsonObject b)=>{Billing.Require(mail.Enabled,"Email delivery is not configured.");var email=Email(b.Text("email"));await store.Transaction("identity:"+email,async c=>{var users=await Store.Rows(c,"SELECT * FROM app_user WHERE lower(email)=@p0 AND NOT email_verified AND account_status='Pending'",email);if(users.Count==1)await Token(c,mail,users[0]!,"verify");return 0;});await Task.Delay(300);return Results.Ok(Notice("verify"));}).RequireRateLimiting("identity");
        app.MapPost("/api/auth/verify-email",async(JsonObject b)=>{
            var hash=Store.Hash(b.Text("token"));var owner=await TokenCompany(store,hash,"verify");return await store.Transaction(owner,async c=>{var token=await Store.One(c,"SELECT t.id AS token_id,u.* FROM identity_token t JOIN app_user u ON u.id=t.user_id WHERE t.token_hash=@p0 AND t.purpose='verify' AND t.consumed_at IS NULL AND t.expires_at>now() FOR UPDATE OF t,u",hash);await Store.Exec(c,"UPDATE identity_token SET consumed_at=now() WHERE id=@p0",token.Text("token_id"));await Store.Exec(c,"UPDATE app_user SET email_verified=true WHERE id=@p0",token.Text("id"));await Store.Audit(c,token.Text("company_id"),token.Text("id"),"Email verified",token.Text("id"),new{status="Awaiting administrator approval"});return new{message="Email verified. Your Administrator must approve your account and assign a role before you can sign in."};});
        }).RequireRateLimiting("identity");
        app.MapPost("/api/auth/reset-password",async(JsonObject b)=>{
            Password(Secret(b));Billing.Require(Secret(b)==Secret(b,"confirm_password"),"Passwords do not match.");var hash=Store.Hash(b.Text("token"));var passwordHash=Store.Password(Secret(b));var owner=await TokenCompany(store,hash,"reset");return await store.Transaction(owner,async c=>{var token=await Store.One(c,"SELECT t.id AS token_id,u.* FROM identity_token t JOIN app_user u ON u.id=t.user_id WHERE t.token_hash=@p0 AND t.purpose='reset' AND t.consumed_at IS NULL AND t.expires_at>now() AND u.active AND u.account_status='Approved' AND (u.email_verified OR @p1) FOR UPDATE OF t,u",hash,mail.IsOffline);await Store.Exec(c,"UPDATE app_user SET password_hash=@p0,session_version=session_version+1 WHERE id=@p1",passwordHash,token.Text("id"));await Store.Exec(c,"UPDATE identity_token SET consumed_at=now() WHERE user_id=@p0 AND consumed_at IS NULL",token.Text("id"));await Store.Exec(c,"UPDATE identity_mail SET state='Cancelled',updated_at=now(),encrypted_payload='' WHERE user_id=@p0 AND state='Pending'",token.Text("id"));await QueueMail(c,mail,token,"Your SALES360 password was changed","Your SALES360 password has been reset. Existing sessions were signed out. If you did not make this change, contact your Administrator immediately. Your password is never included in email.");await Store.Audit(c,token.Text("company_id"),token.Text("id"),"Password reset completed",token.Text("id"),new{sessionsRevoked=true});return new{message="Password updated. All existing sessions have been signed out. Sign in with your new password."};});
        }).RequireRateLimiting("identity");
        api.MapPost("/users",async(HttpContext h,JsonObject b)=>{
            Administrator(h);var name=b.Text("name");Billing.Require(name.Length is >=2 and <=120,"Enter the user's full name.");var identity=Enrollment.Identifier(b.Text("identifier"),mail.IsOffline);var email=Accounts.Email(b.Text("email"));Billing.Require(identity.Email==null||identity.Email==email,"Email login and recovery email must match.");Password(Secret(b));Billing.Require(Secret(b)==Secret(b,"confirm_password"),"Passwords do not match.");var access=b.Text("access_role");var duty=b.Text("workflow_role");Billing.Require(AccessRoles.Contains(access)&&WorkflowRoles.Contains(duty),"Choose a valid role and duty.");var areas=AreaAccess.Parse(b["work_areas"],access,duty);
            return await store.Transaction(Company(h),async c=>{
                var existing=await Store.Rows(c,"SELECT id FROM app_user WHERE lower(email)=@p0 OR lower(username)=@p1",email,identity.Username??email);Billing.Require(existing.Count==0,"That email or username is already assigned.");var id=Guid.NewGuid().ToString("N");
                await Store.Exec(c,"INSERT INTO app_user(id,company_id,name,role,password_hash,active,email,username,access_role,account_status,work_areas) VALUES(@p0,@p1,@p2,@p3,@p4,true,@p5,@p6,@p7,'Approved',@p8::jsonb)",id,Company(h),name,duty,Store.Password(Secret(b)),email,identity.Username,access,System.Text.Json.JsonSerializer.Serialize(areas));
                await Store.Audit(c,Company(h),Actor(h),"User created by Administrator",id,new{accessRole=access,workflowRole=duty,workAreas=areas});return Results.Ok(new{id,message="User created. Share the initial password privately; the user can change it in Setting."});
            });
        });
        api.MapGet("/users",async(HttpContext h)=>{Administrator(h);await using var c=await store.Open();return await Store.Rows(c,"SELECT id,name,email,username,email_verified,access_role,role AS workflow_role,work_areas,session_version,account_status,active,registered_at FROM app_user WHERE company_id=@p0 ORDER BY registered_at DESC,name",Company(h));});
        api.MapPost("/users/{id}/access",async(HttpContext h,string id,JsonObject b)=>{Administrator(h);var access=b.Text("access_role");var workflow=b.Text("workflow_role");var status=b.Text("account_status");var areas=AreaAccess.Parse(b["work_areas"],access,workflow);Billing.Require(AccessRoles.Contains(access)&&WorkflowRoles.Contains(workflow)&&new[]{"Approved","Suspended"}.Contains(status),"Choose a valid access role, workflow duty and account status.");return await store.Transaction(Company(h),async c=>{var user=await Store.One(c,"SELECT * FROM app_user WHERE company_id=@p0 AND id=@p1 FOR UPDATE",Company(h),id);Billing.Require(id!=Actor(h),"Use another Administrator to change your own account access.");if(b["expected_session_version"]!=null)Billing.Require(b.Integer("expected_session_version")==user.Integer("session_version"),"User access changed since you opened the row. Refresh before saving.");Billing.Require(status!="Approved"||mail.IsOffline||user["email"]==null||user["email_verified"]!.GetValue<bool>(),"The user must verify their email before activation.");if(user.Text("access_role")=="Administrator"&&user["active"]!.GetValue<bool>()&&(access!="Administrator"||status!="Approved")){var count=(await Store.One(c,"SELECT count(*) AS count FROM app_user WHERE company_id=@p0 AND access_role='Administrator' AND active AND account_status='Approved'",Company(h))).Integer("count");Billing.Require(count>1,"At least one active Administrator must remain.");}await Store.Exec(c,"UPDATE app_user SET access_role=@p0,role=@p1,account_status=@p2,active=@p3,session_version=session_version+1,work_areas=@p5::jsonb WHERE id=@p4",access,workflow,status,status=="Approved",id,JsonSerializer.Serialize(areas));await Store.Audit(c,Company(h),Actor(h),"User access assigned",id,new{before=new{accessRole=user.Text("access_role"),workflowRole=user.Text("role"),status=user.Text("account_status"),workAreas=user["work_areas"]},after=new{accessRole=access,workflowRole=workflow,status,workAreas=areas}});return new{message="User access saved. Existing sessions were revoked."};});});
        api.MapGet("/auth-mail/status",async(HttpContext h)=>{Administrator(h);await using var c=await store.Open();return new{mode=mail.PublicStatus,configured=mail.Enabled,jobs=await Store.Rows(c,"SELECT id,state,attempts,created_at,updated_at,provider_reference,error_code FROM identity_mail WHERE company_id=@p0 ORDER BY created_at DESC LIMIT 30",Company(h))};});
    }
}

public record IdentityMessage(string To,string Subject,string Body);
